// Normaliza (solo licencias comerciales abiertas: BY, BY-SA, BY-ND, CC0).
const LICENSE_MAP = {
  'BY': 'CC-BY',
  'CC-BY': 'CC-BY',
  'BY-SA': 'CC-BY-SA',
  'CC-BY-SA': 'CC-BY-SA',
  'BY-ND': 'CC-BY',
  'CC-BY-ND': 'CC-BY',
  'CC0': 'CC0',
  'CC0 1.0': 'CC0',
  'Public Domain': 'CC0',
};
const PATTERNS = [
  /[-–—|/•]?\s*(free\s*(to\s*)?sell|free\s*commercial\s*(use|license)?|commercial\s*(use|license|friendly)(\s*allowed)?|for\s*commercial\s*use|libre\s*comercial|uso\s*comercial(\s*libre)?)\b/gi,
  /[-–—|/•]?\s*(no |sin )?(ams|supports?|soportes?)\b/gi,
  /[-–—|/•]?\s*(easy\s*(to\s*)?print(ing)?|f[aá]cil\s*de\s*imprimir)\b/gi,
  /[-–—|/•]?\s*print\s*in\s*place\b/gi,
  /[-–—|/•]?\s*\b(p-i-p|pip)\b/gi,
  /\|?\s*免支撑\S*/g,
  /\|?\s*多色一盘\S*/g,
  /\|?\s*参数优化\S*/g,
  /\|?\s*模型优化\S*/g,
  /[-–—|/•]?\s*\d+\.?\d*mm\s*layer\b.*$/i,
  /[-–—|/•]?\s*\d+\s*walls?\b.*$/i,
  /[-–—|/•]?\s*\d+%\s*infill\b.*$/i,
];
function cleanTitle(t) {
  if (!t) return 'Sin título';
  let out = String(t);
  for (const p of PATTERNS) out = out.replace(p, '');
  out = out.replace(/^\s*[-–—|/•:;,]\s*/g, '').replace(/\s*[-–—|/•:;,]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  return out.length >= 2 ? out : 'Sin título';
}
const res = items.map(({ json: d }) => {
