const GEMINI_API_KEY = $env.GEMINI_API_KEY || "TU_API_KEY_AQUI";
const GEMINI_URL = `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${GEMINI_API_KEY.trim()}`;
const flareUserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64)";

