let cookieString = "";
try {
    const cookies = $("MakerWorld: search").first().json.solution.cookies || [];
    cookieString = cookies.map(c => `${c.name}=${c.value}`).join("; ");
} catch(e) {}

for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p.title) continue;
    if (GEMINI_API_KEY.includes("TU_API_KEY_AQUI") || GEMINI_API_KEY.trim() === "") {
        p.description = "ERROR: OLVIDASTE PONER TU API KEY DE GEMINI EN EL NODO DE CODIGO!";
        continue;
    }

    // Mapeo de todas las imgenes disponibles para Mercado Libre
    let base64Images = []; // Para enviar a Gemini
    p.meli_pictures = []; // Para Mercado Libre

    try {
        const imgUrls = p.images && p.images.length > 0 ? p.images : (p.imageUrl ? [p.imageUrl] : []);

        for (let idx = 0; idx < Math.min(imgUrls.length, 3); idx++) { // Max 3 imagenes para Gemini
            const imgUrl = imgUrls[idx];
            if (!imgUrl) continue;
            p.meli_pictures.push({ source: imgUrl }); // Para el Payload de Meli

            const imgBuffer = await this.helpers.httpRequest({
                method: 'GET',
                url: imgUrl,
                encoding: null,
                responseType: 'arraybuffer',
                timeout: 5000,
                headers: {
                    'User-Agent': flareUserAgent,
                    'Accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
                    'Sec-Fetch-Dest': 'image',
                    'Sec-Fetch-Mode': 'no-cors',
                    'Sec-Fetch-Site': 'cross-site',
                    'Referer': 'https://makerworld.com/',
                    'Cookie': cookieString
                }
            });
            if (imgBuffer && imgBuffer.length > 500) {
                let mimeType = null;
                const header = imgBuffer.slice(0, 4).toString("hex").toUpperCase();
                if (header.startsWith("89504E47")) mimeType = "image/png";
                else if (header.startsWith("52494646")) mimeType = "image/webp";
                else if (header.startsWith("FFD8FF")) mimeType = "image/jpeg";

                if (mimeType) {
                    base64Images.push({
                        mimeType: mimeType,
                        data: Buffer.from(imgBuffer).toString("base64")
                    });
                }
            }
        }
    } catch (imgErr) {
        console.log("Error descargando imagen para Gemini:", imgErr.message);
    }

    await new Promise(r => setTimeout(r, 2000));

    // Si no hay variantes, creamos una default
    if (!p.variants || p.variants.length === 0) {
        p.variants = [{ name: "Estandar", grams: 50, price: 100 }];
    }

    const variantsInfo = p.variants.map((v, i) => `[${i+1}] ${v.name} (${v.grams}g, $${v.price})`).join(', ');

    const prompt = `Analiza el siguiente producto para publicarlo en una tienda e-commerce de decoracion y accesorios:
Ttulo Original: ${p.title}
Descripcin original: ${p.description?.slice(0, 500)}
Variantes Fisicas Disponibles (nombre, peso, precio): ${variantsInfo}

REGLA CRITICA DE NEGOCIO:
Tu eres una tienda online que vende el producto FISICO final. El cliente es un comprador normal (no sabe de 3D).
