// === Resolver de categoría MELI v3 (Filtro estricto de dominios, candidatos válidos y Gemini con fallback seguro a MLM3530) ===
async function resolveMeliCategory(ctx, { title, description = '', extraTerms = [], token, geminiKey }) {
  const BAD_ROOTS = [
    'agro', 'peluqueria', 'peluquería', 'extensiones', 'belleza y cuidado personal',
    'alimentos y bebidas', 'salud y equipamiento médico', 'salud y equipamiento medico',
    'bebés', 'bebes', 'ropa, bolsas y calzado', 'maquinaria agrícola', 'maquinaria agricola',
    'plataformas vibratorias', 'paneles solares', 'repuestos maquinaria agrícola',
    'repuestos maquinaria agricola', 'vehículos', 'vehiculos', 'refacciones autos',
    'refacciones de línea pesada'
  ];

  const FORBIDDEN_CAT_IDS = new Set([
    'MLM3530', 'MLM1228', 'MLM1953',
    'MLM187619', // Micrómetros
    'MLM180875', // Paneles Solares
    'MLM456878', // Plataforma agrícola
    'MLM431655', // Cola de Caballo
    'MLM189080', // Básculas de Laboratorio
    'MLM457153'  // Básculas de Precisión
  ]);

  const H = { 'User-Agent': 'Mozilla/5.0', ...(token ? { Authorization: `Bearer ${token}` } : {}) };
  const clean = (t) => String(t || '').replace(/[|·—–\-_/()\[\]"!¡¿?:,.]/g, ' ')
    .replace(/\b(3d|impreso|impresa|impresi[oó]n|pla|petg|stl|decorativ[oa]|articulad[oa]|premium|original|micromedidor|micrometro|micrómetro)\b/gi, ' ')
    .replace(/\s{2,}/g, ' ').trim();

  const http = async (url) => {
    for (const h of [H, { 'User-Agent': 'Mozilla/5.0' }]) {
      try { return await ctx.helpers.httpRequest({ method: 'GET', url, headers: h, timeout: 8000 }); } catch (e) {}
    }
    return null;
  };

  const predict = async (q) => {
    const r = await http(`https://api.mercadolibre.com/sites/MLM/domain_discovery/search?q=${encodeURIComponent(q)}&limit=5`);
    return Array.isArray(r) ? r.filter(c => c?.category_id && !FORBIDDEN_CAT_IDS.has(c.category_id)) : [];
  };

  const gemini = async (prompt) => {
    const g = await ctx.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${geminiKey}`,
      headers: { 'Content-Type': 'application/json' },
      body: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 0.1 } },
      timeout: 15000
    });
    return JSON.parse((g?.candidates?.[0]?.content?.parts?.[0]?.text || '{}').replace(/```json|```/g, '').trim());
  };

  const t = clean(title);
  const queries = [
    clean(extraTerms[0] || ''),
    t,
    clean(t.split(' ').slice(0, 3).join(' ')),
    ...extraTerms.slice(1).map(x => clean(x)),
    clean(String(description).split(/[.!]/)[0]).slice(0, 80)
  ].filter((q, idx, arr) => Boolean(q && q.length >= 3 && arr.indexOf(q) === idx));

  const rawCandidateMap = new Map();
  for (const q of queries) {
    const preds = await predict(q);
    for (const c of preds) {
      if (c?.category_id && !FORBIDDEN_CAT_IDS.has(c.category_id) && !rawCandidateMap.has(c.category_id)) {
        rawCandidateMap.set(c.category_id, c);
      }
    }
  }

  const validCandidates = [];
  for (const [cid, c] of rawCandidateMap.entries()) {
    const cat = await http(`https://api.mercadolibre.com/categories/${cid}`);
    if (!cat) continue;
    const leaf = !Array.isArray(cat.children_categories) || cat.children_categories.length === 0;
    const allowed = cat?.settings?.listing_allowed !== false && cat?.settings?.buying_allowed !== false;
    const fullBreadcrumb = (cat.path_from_root || []).map(p => p.name).join(' > ');
    const pathLower = fullBreadcrumb.toLowerCase();
    const isBad = BAD_ROOTS.some(bad => pathLower.includes(bad));

    if (leaf && allowed && !isBad) {
      validCandidates.push({ id: cid, name: cat.name || c.category_name || '', path: fullBreadcrumb });
    }
  }

  if (validCandidates.length === 0) {
    return { id: 'MLM3530', name: 'Otros', path: 'Otras Categorías > Otros', meliTitle: null, method: 'fallback' };
  }

  let chosen = validCandidates[0];
  let meliTitle = null;
  let method = 'first_candidate';

  if (geminiKey) {
    try {
      let optionsPrompt = '0. [MLM3530] Otras Categorías > Otros (Usa esta opción si NINGUNA de las siguientes coincide de forma natural y segura con lo que el objeto ES físicamente)\n';
      validCandidates.forEach((vc, idx) => {
        optionsPrompt += `${idx + 1}. [${vc.id}] ${vc.path}\n`;
      });

      const prompt = `Eres experto en catalogación de Mercado Libre México.
Producto físico:
TÍTULO: ${title}
DESCRIPCIÓN: ${String(description).slice(0, 400)}
PISTAS: ${extraTerms.filter(Boolean).join(' | ')}

Candidatos encontrados en Mercado Libre:
