// Lee la salida del nodo Gemini para esta iteración del loop
const product = $('Gemini AI Enrich').first().json.products[0];
if (!product) return [];

const cleanTitle = (product.title || '').substring(0, 60);

// Categorización: predictor ML autenticado + Gemini + verificación
let meliToken = null;
try {
  const tk = await this.helpers.httpRequest({ method: 'GET', url: 'http://task_backend:3000/api/meli/token', headers: { Authorization: `Bearer ${($env.SYNC_SECRET || '').trim()}` }, timeout: 10000 });
  meliToken = tk?.accessToken || tk?.access_token || null;
} catch (e) {}

const catRes = await resolveMeliCategory(this, {
  title: cleanTitle, description: product.description || '',
  extraTerms: [product.meli_search_term, product.category],
  token: meliToken, geminiKey: ($env.GEMINI_API_KEY || '').trim()
});
const resolvedCategoryId = catRes.id;
const finalTitle = (catRes.meliTitle || cleanTitle).substring(0, 58);

const nonGifPics = (product.meli_pictures || []).filter(pic => pic?.source && !/\.gif(\?|$)/i.test(pic.source));
const picturesForMeli = nonGifPics.length > 0 ? nonGifPics : (product.meli_pictures || []);

const payload = {
  title: finalTitle,
  family_name: finalTitle,
  category_id: resolvedCategoryId,
  price: product.variants && product.variants.length > 0 ? product.variants[0].price : 100,
  currency_id: "MXN",
  available_quantity: 5,
  buying_mode: "buy_it_now",
  condition: "new",
  listing_type_id: "gold_special",
  pictures: picturesForMeli,
  variations: product.meli_variations || []
};

// Mercado libre no quiere 'variations' si la lista viene vacía
if (payload.variations.length === 0) {
  delete payload.variations;
}

return [{ json: payload }];
